// === Tab: mySketch ===
/*	
#WCCChallenge for February 11, 2024
Topic: 🍄 Space-filling algorithms
https://openprocessing.org/sketch/2173992
#CreativeCoding #GenerativeArt #p5JS
*/

var particle_array, move_layer, static_layer, ratio
var subdivisions = 250 // be careful about making this too large
const completion_ratio = 0.02 // this will determine how filled in it gets, based on the amount of edge contact.
// should be between 0 and 1. 
// 0.02 would be barely contacting, 1 would be contacting all the way around.
var extend_range = -1.5 // set this to 0 to have squares. It produces a fine, sparse texture. I favor 1-2 (in cell_size units)
var	rotation_range = -0.1 // in radians
var streaking = -1 // set to 0 or 1 to override off or on, otherwise, it will be a random choice 
// Set to a negative number to have it randomized between short, medium, and long.
// Very long extensions makes for more of a tepestry style image. For that, a lower opacity may be better.
const opacity = 70

function setup(init = true) {
	frameRate(60) // if you have a faster computer/monitor, feel free to set this higher.
	pixelDensity(1) // ditto.
	W = windowWidth
	H = windowHeight
	S = min(W, H)
	subdivisions = min(subdivisions, S / 2)
	cell_size = int(S / subdivisions)
	cell_size2 = cell_size / 2
	cell_count_x = int(W / cell_size)
	cell_count_y = int(H / cell_size)
	particle_count = int((cell_count_x + cell_count_y) * 2)
	particle_count_initial = particle_count
	W = cell_size * cell_count_x
	H = cell_size * cell_count_y
	S = min(W,H)
	// proportion = H / W * 0.5

	if (init) {
		createCanvas(W, H)
		move_layer = createGraphics(W, H)
		static_layer = createGraphics(W, H)
		if(extend_range < 0) extend_range = random([random([0,1]), random([2,3]),random(S/30),random(S/15)]) 
		if(rotation_range < 0){
			if(extend_range == 0) rotation_range = 0 
			else rotation_range = random([0,random(0.15)])
		}
		if(streaking < 0) streaking = random() < 0.25? 1 : 0
	} else {
		resizeCanvas(W, H)
		move_layer.resizeCanvas(W, H)
		static_layer.resizeCanvas(W, H)
	}

	W_actual = int(W * pixelDensity())
	H_actual = int(H * pixelDensity())

	move_layer.noStroke()
	static_layer.noStroke()
	if(!streaking) static_layer.background(125, 125, 150)

	particle_array = []
	static_array = []
	seed_cell = [int(cell_count_x / 2), int(cell_count_y / 2)]
	static_array = new Array(cell_count_y).fill(0).map(() => new Array(cell_count_x).fill(0))
	static_array[seed_cell[1]][seed_cell[0]] = 10
	static_layer.fill(0, 180)
	static_layer.square(seed_cell[0] * cell_size, seed_cell[1] * cell_size, cell_size)

	for (let i = 0; i < particle_count; i++) {
		particle_array.push(new particle())
	}
	t = 0
	mX = 0
}

function draw() {
	// if(((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))){
	// 	mX = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))
	// 	extend_range = mX/3
	// } 
	const ratio = particle_count / particle_count_initial
	const complete = ratio < (1 - completion_ratio)
	if(streaking) move_layer.background(125, 125, 150,30)
	else move_layer.clear()
	for (let i = particle_array.length - 1; i >= 0; i--) {
		particle_array[i].draw()
		particle_array[i].update()
		if (particle_array[i].remove) particle_array.splice(i, 1)
	}
	let _wG_1 = 0; while ((particle_array.length < particle_count) && ++_wG_1 < 20000) { // && !complete){
		particle_array.push(new particle())
	}
	// move_layer.filter(BLUR,4)
	if(streaking){
		image(move_layer, 0, 0)
		image(static_layer, 0, 0)	
	}
	else{
		image(static_layer, 0, 0)
		image(move_layer, 0, 0)
	}

	// if(particle_array.length == 0) noLoop()
	if (complete) noLoop()
}

class particle {
	constructor() {
		this.remove = false
		this.adhere = false
		this.vertical = Math.random() > 0.5 //proportion
		this.vx = 0
		this.vy = 0
		this.height = 1
		this.width = 1
		this.x0 = 0
		this.y0 = 0
		this.extend = random(0, extend_range)
		// this.thickness = random(0.5,1.5) * cell_size // too tricky to implement for now
		if (this.vertical) {
			this.cell_y = random([0, cell_count_y - 1])
			// this.cell_x = constrain(int(randomGaussian(cell_count_x/2,cell_count_x/6)),0,cell_count_x-1) // cool alternate config.
			this.cell_x = int(random(cell_count_x))
			this.height += this.extend
			if (this.cell_y == 0) {
				this.vy = 1
				this.y0 -= this.extend
				this.color = [255, 240, 230, opacity * 1.5]
			} else {
				this.vy = -1
				this.color = [0, 0, 25, opacity]
			}
			this.x1 = this.cell_x * cell_size
			this.y1 = this.cell_y * cell_size - this.vy * this.extend
		} else {
			this.cell_x = random([0, cell_count_x - 1])
			// this.cell_y = constrain(int(randomGaussian(cell_count_y/2,cell_count_y/6)),0,cell_count_y-1)
			this.cell_y = int(random(cell_count_y))
			this.width += this.extend
			if (this.cell_x == 0) {
				this.vx = 1
				this.x0 -= this.extend
				this.color = [255, 20, 0, opacity]
			} else {
				this.vx = -1
				this.color = [0, 255, 20, opacity]
			}
			this.x1 = this.cell_x * cell_size - this.vx * this.extend
			this.y1 = this.cell_y * cell_size
		}
		this.width *= cell_size
		this.height *= cell_size
		this.x = this.cell_x * cell_size
		this.y = this.cell_y * cell_size
		this.x0 *= cell_size
		this.y0 *= cell_size
	}

	update() {
		//check area
		for (let x = -1; x <= 1; x++) {
			for (let y = -1; y <= 1; y++) {
				const val = static_array[constrain(this.cell_y + y, 0, cell_count_y - 1)][constrain(this.cell_x + x, 0, cell_count_x - 1)]
				if (Math.random() < val / 10) {
					this.adhere = true
					static_array[this.cell_y][this.cell_x] += 1
					if (static_array[this.cell_y][this.cell_x] == 10) particle_count--
					return
				}
			}
		}
		if (this.vertical) {
			this.cell_y += this.vy
			this.cell_x = constrain(this.cell_x + random([-1, 0, 0, 1]), 0, cell_count_x - 1)
			this.x = this.cell_x * cell_size
			this.y += this.vy * cell_size
			const end_pos = this.y + this.vy * this.height 
			// not exactly the condition I was going for, but I like this effect better, and it's slightly more efficient I guess.
			if (end_pos < 0 || end_pos > H) this.remove = true
		} 
		else {
			this.cell_x += this.vx
			this.cell_y = constrain(this.cell_y + random([-1, 0, 0, 1]), 0, cell_count_y - 1)
			this.x += this.vx * cell_size
			this.y = this.cell_y * cell_size
			const end_pos = this.x + this.vx * this.width
			if (end_pos < 0 || end_pos > W) this.remove = true
		}
	}

	draw() {
		if (this.remove) return
		if (this.adhere) {
			static_layer.fill(...this.color)
			static_layer.push()
			static_layer.translate(this.x, this.y)
			static_layer.rotate(random(-rotation_range,rotation_range))
			static_layer.rect(this.x0,this.y0, this.width, this.height)
			static_layer.pop()
			this.remove = true
		} else {
			move_layer.fill(...this.color)
			move_layer.rect(this.x + this.x0, this.y + this.y0, this.width, this.height)
		}
	}
}


function keyPressed() {
	if (key === 's') save_img()
	else if (key === 'r') setup()
	else if (key === 'f') {
		if (fullscreen()) fullscreen(false)
		else go_fullscreen()
	}
}

function mousePressed() {
	if (touches.length > 0) go_fullscreen()
}

